export function deck(rng=Math.random){let d=[];for(const s of ['♠','♥','♣','♦'])for(let r=2;r<=14;r++)d.push({r,s});for(let i=51;i>0;i--){let j=Math.floor(rng()*(i+1));[d[i],d[j]]=[d[j],d[i]]}return d}
export const rankName=['高牌','一对','两对','三条','顺子','同花','葫芦','四条','同花顺'];
export function compare(a,b){for(let i=0;i<Math.max(a.length,b.length);i++){let x=(a[i]||0)-(b[i]||0);if(x)return x}return 0}
function five(cs){let rs=cs.map(c=>c.r).sort((a,b)=>b-a),g={};rs.forEach(r=>g[r]=(g[r]||0)+1);let groups=Object.entries(g).map(([r,n])=>[n,+r]).sort((a,b)=>b[0]-a[0]||b[1]-a[1]);let u=[...new Set(rs)],st=u.length===5&&u[0]-u[4]===4?u[0]:u.join(',')==='14,5,4,3,2'?5:0,fl=cs.every(c=>c.s===cs[0].s);if(fl&&st)return[8,st];if(groups[0][0]===4)return[7,groups[0][1],groups[1][1]];if(groups[0][0]===3&&groups[1][0]===2)return[6,groups[0][1],groups[1][1]];if(fl)return[5,...rs];if(st)return[4,st];if(groups[0][0]===3)return[3,groups[0][1],...groups.slice(1).map(g=>g[1])];if(groups[0][0]===2&&groups[1][0]===2)return[2,...groups.map(g=>g[1])];if(groups[0][0]===2)return[1,...groups.map(g=>g[1])];return[0,...rs]}
export function evaluate(cs){let best=[-1];for(let a=0;a<cs.length-4;a++)for(let b=a+1;b<cs.length-3;b++)for(let c=b+1;c<cs.length-2;c++)for(let d=c+1;d<cs.length-1;d++)for(let e=d+1;e<cs.length;e++){let v=five([cs[a],cs[b],cs[c],cs[d],cs[e]]);if(compare(v,best)>0)best=v}return best}
export function points(cs){let v=cs.reduce((n,c)=>n+(c.r===14?11:Math.min(c.r,10)),0),aces=cs.filter(c=>c.r===14).length;while(v>21&&aces-->0)v-=10;return v}
export function distribute(players,board){const levels=[...new Set(players.map(p=>p.total).filter(Boolean))].sort((a,b)=>a-b);let paid=players.map(()=>0),previous=0;for(let level of levels){let contributors=players.map((p,i)=>i).filter(i=>players[i].total>=level),amount=(level-previous)*contributors.length;let eligible=contributors.filter(i=>!players[i].fold);if(!eligible.length){contributors.forEach(i=>paid[i]+=amount/contributors.length);previous=level;continue}let scores=eligible.map(i=>({i,v:evaluate([...players[i].cards,...board])}));scores.sort((a,b)=>compare(b.v,a.v));let winners=scores.filter(s=>compare(s.v,scores[0].v)===0);winners.forEach((w,j)=>paid[w.i]+=Math.floor(amount/winners.length)+(j<amount%winners.length?1:0));previous=level}return paid}
// Direct rank evaluator for Monte Carlo rollouts; equivalent ordering to evaluate().
export function fastRank(cs){const cnt=Array(15).fill(0),suits={'♠':[],'♥':[],'♣':[],'♦':[]};for(const c of cs){cnt[c.r]++;suits[c.s].push(c.r)}const ranks=[];for(let r=14;r>=2;r--)if(cnt[r])ranks.push(r);function straight(rs){const v=new Set(rs);if(v.has(14))v.add(1);for(let r=14;r>=5;r--)if([0,1,2,3,4].every(d=>v.has(r-d)))return r;return 0}let flush=Object.values(suits).find(s=>s.length>=5);if(flush){let st=straight(flush);if(st)return[8,st]}const quads=ranks.filter(r=>cnt[r]===4),trips=ranks.filter(r=>cnt[r]>=3),pairs=ranks.filter(r=>cnt[r]>=2);if(quads.length)return[7,quads[0],ranks.find(r=>r!==quads[0])];if(trips.length&&pairs.some(r=>r!==trips[0]))return[6,trips[0],pairs.find(r=>r!==trips[0])];if(flush)return[5,...flush.sort((a,b)=>b-a).slice(0,5)];const st=straight(ranks);if(st)return[4,st];if(trips.length)return[3,trips[0],...ranks.filter(r=>r!==trips[0]).slice(0,2)];if(pairs.length>=2)return[2,...pairs.slice(0,2),ranks.find(r=>!pairs.slice(0,2).includes(r))];if(pairs.length)return[1,pairs[0],...ranks.filter(r=>r!==pairs[0]).slice(0,3)];return[0,...ranks.slice(0,5)]}
